// ============================================================================
// CCIX_Cache_Coherent_Interconnect_apb: APB4 register wrapper around CCIX_Cache_Coherent_Interconnect_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/CCIX_Cache_Coherent_Interconnect.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/CCIX_Cache_Coherent_Interconnect.md
// ============================================================================
module CCIX_Cache_Coherent_Interconnect_apb #(
  parameter int MAXP = 16,
  // TLP payload words (8..1023)
  parameter int NREQ = 2,
  // Request credits granted (1..15)
  parameter int NSNP = 2,
  // Snoop credits granted (1..15)
  parameter int RXD  = 64,
  // receive buffer words (power of 2, more than 8 * (NREQ + NSNP))
  parameter int CRT  = 16
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic tlp_tx_valid,
  input logic tlp_tx_ready,
  output logic [31:0] tlp_tx_data,
  output logic tlp_tx_last,
  input logic tlp_rx_valid,
  input logic [31:0] tlp_rx_data,
  input logic tlp_rx_last
);
  localparam logic [31:0] ID_VALUE = 32'h43430200;

  // ---------------- core ----------------
  logic [15:0]   c_rid;
  logic [15:0]   c_tgt_rid;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [31:0]   c_tx_data;
  logic          c_rx_valid;
  logic          c_rx_ready;
  logic [31:0]   c_rx_data;
  logic          c_rx_last;
  logic [4:0]    c_tx_crd_req;
  logic [4:0]    c_tx_crd_snp;
  logic          c_ev_err;
  logic          c_ev_nocrd;
  logic          c_ev_ovf;
  CCIX_Cache_Coherent_Interconnect_top #(.MAXP(MAXP), .NREQ(NREQ), .NSNP(NSNP), .RXD(RXD), .CRT(CRT)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .rid(c_rid),
    .tgt_rid(c_tgt_rid),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_data(c_tx_data),
    .rx_valid(c_rx_valid),
    .rx_ready(c_rx_ready),
    .rx_data(c_rx_data),
    .rx_last(c_rx_last),
    .tlp_tx_valid(tlp_tx_valid),
    .tlp_tx_ready(tlp_tx_ready),
    .tlp_tx_data(tlp_tx_data),
    .tlp_tx_last(tlp_tx_last),
    .tlp_rx_valid(tlp_rx_valid),
    .tlp_rx_data(tlp_rx_data),
    .tlp_rx_last(tlp_rx_last),
    .tx_crd_req(c_tx_crd_req),
    .tx_crd_snp(c_tx_crd_snp),
    .ev_err(c_ev_err),
    .ev_nocrd(c_ev_nocrd),
    .ev_ovf(c_ev_ovf)
  );

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [9:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd10) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- registers ----------------
  logic [5:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [31:0] r_ID_CFG;   // 12'h014 ID_CFG
  logic [31:0] h_TX;   // 12'h018 TX holding register
  logic [31:0] h_RX0;   // 12'h01C RX0 holding register
  logic [0:0] h_RX1;   // 12'h020 RX1 holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_ID_CFG <= 32'h0;
      h_TX <= '0;
      h_RX0 <= '0;
      h_RX1 <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[5:0] & wmask[5:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[5:0]) | (PWDATA[5:0] & wmask[5:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_ID_CFG <= (r_ID_CFG & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[6] && !full_TX) h_TX <= (h_TX & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[6] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[8]))) begin
        h_RX0[31:0] <= c_rx_data[31:0];
        h_RX1 <= c_rx_last;
        avail_RX <= 1'b1;
      end else if (rd && hit[8]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_rid = r_ID_CFG[15:0];
  assign c_tgt_rid = r_ID_CFG[31:16];
  assign c_tx_data[31:0] = h_TX[31:0];
  assign c_tx_valid = full_TX;
  assign c_rx_ready = ~avail_RX | (rd & hit[8]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_ev_err;
    irq_set[1] = c_ev_nocrd;
    irq_set[2] = c_ev_ovf;
    irq_set[3] = full_TX & c_tx_ready;
    irq_set[4] = wr & (hit[6]) & full_TX;
    irq_set[5] = c_rx_valid & (~avail_RX | (rd & hit[8]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd3: rdata = 32'(flags);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(r_ID_CFG);
      10'd6: rdata = 32'(h_TX);
      10'd7: rdata = 32'(h_RX0);
      10'd8: rdata = 32'(h_RX1);
      10'd9: rdata = 32'({c_tx_crd_snp, c_tx_crd_req});
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
